_elementor_page_settings.custom_css:
@import url('https://fonts.googleapis.com/css2?family=Open+Sans:ital,wght@0,300..900;1,300..900&display=swap');

html, body {
  font-family: 'Open Sans', sans-serif !important;
}

h1, .e-default-h1, h2, h3, h4, p, span, a, div {
  font-family: 'Open Sans', sans-serif !important;
}

h1 span:last-of-type,
.e-default-h1 span:last-of-type {
  background: linear-gradient(90deg, #FFCF00 0%, #FF5500 100%) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  display: inline-block !important;
}
